import random


def generate(seed: int = 0) -> list[str]:
    """All generated arguments stay within the statement bounds and follow the problem guarantees."""
    r = random.Random(seed)
    cases = [[17, 18, 5, 4, 6, 1], [400]]
    seen = {tuple(x) for x in cases}
    while len(cases) < 600:
        a = [r.randint(1, 100000) for _ in range(r.randint(1, 100))]
        key = tuple(a)
        if key not in seen:
            seen.add(key)
            cases.append(a)
    return [f"candidate(arr={a!r})" for a in cases]


